DELIMITER $$
CREATE PROCEDURE sp_register_exam(IN p_exam INT UNSIGNED,IN p_enrollment INT UNSIGNED,IN p_hall INT UNSIGNED)
BEGIN IF NOT EXISTS(SELECT 1 FROM exam WHERE exam_id=p_exam AND registration_open=1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Exam registration is closed'; END IF; IF NOT EXISTS(SELECT 1 FROM exam ex JOIN enrollment e ON e.offering_id=ex.offering_id WHERE ex.exam_id=p_exam AND e.enrollment_id=p_enrollment AND e.status='ENROLLED') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Active enrollment in the exam offering required'; END IF; IF fn_attendance_percentage(p_enrollment)<75 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Attendance below 75 percent'; END IF; INSERT INTO exam_registration(exam_id,enrollment_id,exam_hall_id) VALUES(p_exam,p_enrollment,p_hall); SELECT LAST_INSERT_ID() exam_registration_id; END$$
CREATE PROCEDURE sp_submit_marks(IN p_registration INT UNSIGNED,IN p_marks DECIMAL(5,2),IN p_faculty INT UNSIGNED)
BEGIN DECLARE v_exam INT UNSIGNED DEFAULT NULL; DECLARE v_offering INT UNSIGNED; DECLARE v_max DECIMAL(5,2); DECLARE v_grade_id INT UNSIGNED; SELECT ex.exam_id,ex.offering_id,ex.max_marks INTO v_exam,v_offering,v_max FROM exam_registration er JOIN exam ex ON ex.exam_id=er.exam_id WHERE er.exam_registration_id=p_registration; IF v_exam IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid exam registration'; END IF; IF p_faculty IS NOT NULL AND NOT EXISTS(SELECT 1 FROM course_allocation ca WHERE ca.offering_id=v_offering AND ca.faculty_id=p_faculty) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Faculty is not assigned to this offering'; END IF; IF p_marks IS NULL OR p_marks<0 OR p_marks>v_max THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid marks value'; END IF; IF EXISTS(SELECT 1 FROM exam WHERE exam_id=v_exam AND results_published=1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Published marks are locked'; END IF; SELECT grade_scale_id INTO v_grade_id FROM grade_scale WHERE minimum_percent<=p_marks/v_max*100 ORDER BY minimum_percent DESC LIMIT 1; INSERT INTO marks(exam_registration_id,marks_obtained,grade_scale_id,entered_by) VALUES(p_registration,p_marks,v_grade_id,p_faculty) ON DUPLICATE KEY UPDATE marks_obtained=VALUES(marks_obtained),grade_scale_id=VALUES(grade_scale_id),entered_by=VALUES(entered_by); SELECT p_registration exam_registration_id; END$$
CREATE PROCEDURE sp_publish_results(IN p_exam INT UNSIGNED)
BEGIN DECLARE v_sem INT UNSIGNED; DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END; START TRANSACTION; IF NOT EXISTS(SELECT 1 FROM exam WHERE exam_id=p_exam) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Exam not found'; END IF; UPDATE exam SET results_published=1,registration_open=0 WHERE exam_id=p_exam; SELECT co.semester_id INTO v_sem FROM exam ex JOIN course_offering co ON co.offering_id=ex.offering_id WHERE ex.exam_id=p_exam; INSERT INTO result_summary(student_id,semester_id,sgpa,cgpa) SELECT DISTINCT e.student_id,v_sem,fn_student_sgpa(e.student_id,v_sem),ROUND((COALESCE((SELECT SUM(rs.sgpa) FROM result_summary rs WHERE rs.student_id=e.student_id AND rs.semester_id<>v_sem),0)+fn_student_sgpa(e.student_id,v_sem))/(COALESCE((SELECT COUNT(*) FROM result_summary rs WHERE rs.student_id=e.student_id AND rs.semester_id<>v_sem),0)+1),2) FROM exam_registration er JOIN enrollment e ON e.enrollment_id=er.enrollment_id WHERE er.exam_id=p_exam ON DUPLICATE KEY UPDATE sgpa=VALUES(sgpa),cgpa=VALUES(cgpa); COMMIT; END$$
CREATE PROCEDURE sp_request_revaluation(IN p_student INT UNSIGNED,IN p_marks INT UNSIGNED,IN p_reason VARCHAR(500))
BEGIN IF NOT EXISTS(SELECT 1 FROM marks m JOIN exam_registration er ON er.exam_registration_id=m.exam_registration_id JOIN exam ex ON ex.exam_id=er.exam_id JOIN enrollment e ON e.enrollment_id=er.enrollment_id WHERE m.marks_id=p_marks AND e.student_id=p_student AND ex.results_published=1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Published result for this student not found'; END IF; IF CHAR_LENGTH(TRIM(p_reason))<5 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Revaluation reason is required'; END IF; INSERT INTO revaluation_request(marks_id,reason) VALUES(p_marks,p_reason); SELECT LAST_INSERT_ID() revaluation_request_id; END$$
CREATE PROCEDURE sp_decide_revaluation(IN p_request INT UNSIGNED,IN p_approve TINYINT)
BEGIN UPDATE revaluation_request SET status=IF(p_approve=1,'APPROVED','REJECTED') WHERE revaluation_request_id=p_request AND status='PENDING'; IF ROW_COUNT()<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Revaluation request not pending'; END IF; SELECT p_request revaluation_request_id; END$$
DELIMITER ;
